def arrow(id_, a, sa, b, sb, dashed=False, color="#1e1e1e", vx=None):
    """vx: force a vertical arrow at this x (bind only the end that really sits there)."""
    A, B = byid[a], byid[b]
    sx, sy = side(A, sa); ex, ey = side(B, sb)
    bind_a = bind_b = True
    if vx is not None:
        if A["x"] <= vx <= A["x"] + A["width"] and A["width"] < 1000:
            ex = sx = vx; bind_b = False
        else:
            sx = ex = vx; bind_a = False
    ar = base("arrow", id_, sx, sy, abs(ex - sx), abs(ey - sy))
    ar.update({
        "strokeColor": color, "points": [[0, 0], [ex - sx, ey - sy]], "lastCommittedPoint": None,
        "startBinding": {"elementId": a, "focus": 0, "gap": 4} if bind_a else None,
        "endBinding": {"elementId": b, "focus": 0, "gap": 4} if bind_b else None,
        "startArrowhead": None, "endArrowhead": "arrow", "elbowed": False,
